-- N11 TOEIC V44 | 10 chu de, 300 tu, 30 bai hoc (10/20/30 tu tich luy).
-- MySQL 8+, chay tren schema N11 hien tai. Khong tao user, khong xoa/doi du lieu cu.
-- Chay toan bo trong cung mot phien. Neu loi, ROLLBACK truoc khi chay lai.
USE `n11_toeic`;
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Check all required tables/columns BEFORE any permanent insert.
SELECT t.id,l.target_word_count,w.meaning_vi,lt.sort_order FROM vocabulary_topics t
LEFT JOIN vocabulary_lessons l ON l.topic_id=t.id
LEFT JOIN vocabulary_terms w ON w.topic_id=t.id
LEFT JOIN vocabulary_lesson_terms lt ON lt.lesson_id=l.id WHERE 1=0;
SELECT lesson_id,quiz_type,passed FROM vocabulary_quiz_attempts WHERE 1=0;
SELECT question_number,typed_answer FROM vocabulary_quiz_answers WHERE 1=0;
SELECT user_id,lesson_id FROM user_vocabulary_lesson_progress WHERE 1=0;
SELECT user_id,language FROM user_vocabulary_preferences WHERE 1=0;
DROP TEMPORARY TABLE IF EXISTS _n11_v44_topics, _n11_v44_words, _n11_v44_map, _n11_v44_empty;
CREATE TEMPORARY TABLE _n11_v44_topics (title VARCHAR(180) PRIMARY KEY, level VARCHAR(20), description TEXT) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE _n11_v44_words (title VARCHAR(180), pos INT, word VARCHAR(160), meaning_vi VARCHAR(500), example_en TEXT, example_vi TEXT, PRIMARY KEY(title,pos), UNIQUE KEY(title,word)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
START TRANSACTION;
SELECT s.title,s.description,s.level,0,1 FROM _n11_v44_topics s
WHERE NOT EXISTS (SELECT 1 FROM vocabulary_topics t WHERE t.title COLLATE utf8mb4_unicode_ci=s.title COLLATE utf8mb4_unicode_ci);
CREATE TEMPORARY TABLE _n11_v44_map (title VARCHAR(180) PRIMARY KEY, topic_id BIGINT UNSIGNED NOT NULL) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SELECT m.topic_id,s.word,NULL,s.meaning_vi,NULL,s.example_en,s.example_vi,NULL
FROM _n11_v44_words s JOIN _n11_v44_map m ON m.title=s.title
WHERE NOT EXISTS (SELECT 1 FROM vocabulary_terms t WHERE t.topic_id=m.topic_id AND t.word COLLATE utf8mb4_unicode_ci=s.word COLLATE utf8mb4_unicode_ci)
ORDER BY m.topic_id,s.pos;
SELECT m.topic_id,b.title,b.description,b.sort_order,b.target,1
FROM _n11_v44_map m CROSS JOIN (
SELECT 'Bài 1 · Từ vựng cốt lõi' title,'Học 10 từ đầu tiên, luyện thẻ và trắc nghiệm.' description,1 sort_order,10 target
UNION ALL SELECT 'Bài 2 · Mở rộng','Ôn 10 từ cũ và học thêm 10 từ mới.',2,20
UNION ALL SELECT 'Bài 3 · Tổng ôn','Ôn toàn bộ 30 từ trong chủ đề.',3,30
) b
WHERE NOT EXISTS (SELECT 1 FROM vocabulary_lessons l WHERE l.topic_id=m.topic_id AND l.sort_order=b.sort_order);
-- Fill only empty lessons, never reset existing memberships or learning history.
CREATE TEMPORARY TABLE _n11_v44_empty (lesson_id BIGINT UNSIGNED PRIMARY KEY, topic_id BIGINT UNSIGNED, target_count INT, title VARCHAR(180)) DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
WHERE l.sort_order BETWEEN 1 AND 3 AND NOT EXISTS(SELECT 1 FROM vocabulary_lesson_terms lt WHERE lt.lesson_id=l.id);
SELECT l.lesson_id,t.id,s.pos FROM _n11_v44_empty l JOIN _n11_v44_words s ON s.title=l.title AND s.pos<=l.target_count
JOIN vocabulary_terms t ON t.topic_id=l.topic_id AND t.word COLLATE utf8mb4_unicode_ci=s.word COLLATE utf8mb4_unicode_ci;
COMMIT;
-- Report: expected 10 topics / 300 terms / 30 lessons for a clean import.
SELECT m.topic_id,t.title,t.is_published,
 (SELECT COUNT(*) FROM vocabulary_terms w WHERE w.topic_id=t.id) AS words,
 (SELECT COUNT(*) FROM vocabulary_lessons l WHERE l.topic_id=t.id) AS lessons,
 (SELECT COUNT(*) FROM vocabulary_lesson_terms lt JOIN vocabulary_lessons l ON l.id=lt.lesson_id WHERE l.topic_id=t.id) AS lesson_word_links
FROM _n11_v44_map m JOIN vocabulary_topics t ON t.id=m.topic_id ORDER BY m.topic_id;
DROP TEMPORARY TABLE IF EXISTS _n11_v44_topics, _n11_v44_words, _n11_v44_map, _n11_v44_empty;
